from layout import *

def design():
    page('Настоящий решатель','Передача coding задачи','Qwen выбирает одно из двух существующих исправлений по задаче, тексту patch и ограниченной записи проверок.')
    p('Изначально зарегистрированы 500 пар публичных mini-SWE-agent submissions. До чтения официальных исходов выявлено расхождение между множеством trajectory submissions и оцениваемыми patch. После отдельного дополнения основной корпус сформирован из 433 пар Claude и Gemini с непустыми побайтно совпадающими записями и patch.')
    p('По фиксированному hash issue ID выбраны 96 задач. Актёр не видит имя источника. Issue и выдержки patch одинаковы между вариантами памяти. Каждая пара предъявляется в двух обратных порядках. Reader — локальный Qwen3.8-27B Q4_K_M, temperature 0, seed 17112026, native thinking выключен.')
    tbl(['Вариант','Какие сведения дополнительно читает модель'],[
      ['Без записки','Только issue и два patch'],
      ['Последние проверки','До двух последних наблюдаемых проверок'],
      ['Свидетельство и свежесть','Изменение исхода повторного теста и действия после него'],
      ['Переставленные записки','Записка другой задачи того же источника, derangement'],
      ['Strict свидетельство','Консервативно отобранные одиночные test invocations']
    ],[5.0,12.1])
    p('Контроль с перестановкой сохраняет общую длину и содержание записок каждого источника. Он проверяет привязку сведения к задаче. Strict arm добавлен после аудита writer и до открытия исходов. Он меняет достоверность атрибуции одновременно с объёмом доступного свидетельства.')
    h('Что означает успех')
    p('Выбранный patch получает исход из отдельного официального report именно этой submission. Ответы читателя запечатаны до загрузки outcome labels. Основной score усредняет два порядка. Дополнительно есть одно финальное решение с фиксированным tie-break при разногласии.')
    p('На полном корпусе 433 пар простое правило последнего теста выбирает 351 успешный patch, witness-ranking — 344, а prior по другим repository — 353. Дополнительная сложность правила не дала конкурентного выигрыша.')
    p('Официальные labels относятся к историческим серверным запускам февраля и сентября 2026. Они могли использовать разные версии evaluator и среды. Все 433 пары заново в едином текущем harness не исполнялись. Участие публичных задач в обучении Qwen неизвестно. Для общего correctness claim нужен same-harness re-evaluation и новое продолжение агента.')
    source('Закреплённый реестр исторических submissions', 'https://github.com/SWE-bench/experiments/tree/40f164d5b8f1d249bf95a6df8b74b577fd8e519d/evaluation/verified')

def provenance():
    page('Связь с оцениваемым объектом','Происхождение наблюдений','Проверка связи между записью действия и финальным patch изменила основной корпус до открытия исходов.')
    p('В каталоге с названием gpt-5-2-codex конфигурации всех 500 опубликованных траекторий указывают GPT-5.2-2025-12-11. Их ETag и размеры совпадают с каталогом gpt-5-2-high. Из 500 финальных submission только 41 побайтно совпадает с соответствующим evaluator patch. Причина публикационного расхождения по этому аудиту не устанавливается.')
    p('Прежнюю атрибуцию этих исторических трасс модели GPT-5.2-Codex следует исправить на GPT-5.2 из указанного публичного каталога. Исходные численные replay-результаты сохранены. Самостоятельные вызовы Codex в иных опытах имеют собственные журналы.')
    h('Дополнительные публичные заявки')
    tbl(['Проверка публичного snapshot','Количество'],[
      ['Новые папки / с доступными парами','52 / 41'],
      ['По 24 пары на доступную папку','984'],
      ['Непустые с обеих сторон','948'],
      ['Побайтно совпали / различаются','945 / 3'],
      ['Пары с успешными Git patch-id','923'],
      ['Совпали / различаются Git patch-id','921 / 2']
    ],[12.0,5.1])
    p('Все три расхождения сосредоточены в одном gpt-oss-120b submission. Для двух различаются изменённые строки и patch-id. В третьем submission содержит RetryError, Git-сравнение неизвестно. Ещё 36 пар пусты с обеих сторон. Issue повторяются между заявками. Равная квота на папку не оценивает популяционную частоту ошибки. Корректность patch этим аудитом не проверялась.')
    h('Атрибуция shell наблюдения')
    p('Независимый аудит writer нашёл шесть multi-test событий в пяти задачах, одно из них в clean96. Общая диагностика могла быть приписана последнему тесту. Фактическая ошибочность всех verdict не установлена. Strict сохраняет 39 из 325 событий Claude и 469 из 483 Gemini, поэтому его результат включает сильную асимметрию потери покрытия.')
    p('Новый метод должен отличать подтверждённую связь объекта, неизвестную связь и отменённую предпосылку. Прямая проверка hash остаётся обязательным сильным baseline.')
    source('Пример независимого расхождения evaluator patch', 'https://swe-bench-submissions.s3.amazonaws.com/bash-only/20250807_mini-v1.7.0_gpt-oss-120b/logs/django__django-15930/patch.diff')

